lessons.solution:
def parse_score(text):
    score = int(text)
    assert 0 <= score <= 100, 'score out of range'
    return score
for value in ['88', 'high', '120']:
    try:
        print(parse_score(value))
    except ValueError:
        print('not a number')
    except AssertionError:
        print('out of range')
